// 查看数据结构和前几条记录
result = {
  totalRows: data.length,
  columns: Object.keys(data[0]),
  sample: data.slice(0, 5),
  dtypes: Object.fromEntries(Object.keys(data[0]).map(k => [k, typeof data[0][k]]))
};

// 查看period和channel的取值
result = {
  periods: [...new Set(data.map(d => d.period))],
  channels: [...new Set(data.map(d => d.channel))],
  categories: [...new Set(data.map(d => d.category))],
  regions: [...new Set(data.map(d => d.region))]
};

// 分别看基期和本期的汇总: 净销售额和投放额(contribution)
const base = data.filter(d => d.period === '基期');
const current = data.filter(d => d.period === '本期');

const sumBase = {net_sales: base.reduce((s,d)=>s+d.net_sales_cents,0), contribution: base.reduce((s,d)=>s+d.contribution_cents,0)};
const sumCurrent = {net_sales: current.reduce((s,d)=>s+d.net_sales_cents,0), contribution: current.reduce((s,d)=>s+d.contribution_cents,0)};

result = {
  基期: sumBase,
  本期: sumCurrent,
  净销售额变化: ((sumCurrent.net_sales - sumBase.net_sales)/sumBase.net_sales * 100).toFixed(2) + '%',
  投放额变化: ((sumCurrent.contribution - sumBase.contribution)/sumBase.contribution * 100).toFixed(2) + '%',
  基期ROI: (sumBase.net_sales / sumBase.contribution).toFixed(2),
  本期ROI: (sumCurrent.net_sales / sumCurrent.contribution).toFixed(2)
};

// 按渠道分解：各渠道基期vs本期的净销售额和投放
const channels = [...new Set(data.map(d => d.channel))];
const byChannel = channels.map(ch => {
  const b = data.filter(d => d.period==='基期' && d.channel===ch);
  const c = data.filter(d => d.period==='本期' && d.channel===ch);
  const bNet = b.reduce((s,d)=>s+d.net_sales_cents,0);
  const cNet = c.reduce((s,d)=>s+d.net_sales_cents,0);
  const bCon = b.reduce((s,d)=>s+d.contribution_cents,0);
  const cCon = c.reduce((s,d)=>s+d.contribution_cents,0);
  return {
    channel: ch,
    基期净销售: bNet,
    本期净销售: cNet,
    净销售变化率: ((cNet-bNet)/bNet*100).toFixed(1)+'%',
    基期投放: bCon,
    本期投放: cCon,
    投放变化率: ((cCon-bCon)/bCon*100).toFixed(1)+'%',
    基期ROI: (bNet/bCon).toFixed(2),
    本期ROI: (cNet/cCon).toFixed(2)
  };
});
result = byChannel;

// 按品类分解
const categories = [...new Set(data.map(d => d.category))];
const byCategory = categories.map(cat => {
  const b = data.filter(d => d.period==='基期' && d.category===cat);
  const c = data.filter(d => d.period==='本期' && d.category===cat);
  const bNet = b.reduce((s,d)=>s+d.net_sales_cents,0);
  const cNet = c.reduce((s,d)=>s+d.net_sales_cents,0);
  const bCon = b.reduce((s,d)=>s+d.contribution_cents,0);
  const cCon = c.reduce((s,d)=>s+d.contribution_cents,0);
  return {
    category: cat,
    基期净销售: bNet,
    本期净销售: cNet,
    净销售变化率: ((cNet-bNet)/bNet*100).toFixed(1)+'%',
    基期投放: bCon,
    本期投放: cCon,
    投放变化率: ((cCon-bCon)/bCon*100).toFixed(1)+'%',
    基期ROI: (bNet/bCon).toFixed(2),
    本期ROI: (cNet/cCon).toFixed(2)
  };
});
result = byCategory;

// 按区域分解
const regions = [...new Set(data.map(d => d.region))];
const byRegion = regions.map(r => {
  const b = data.filter(d => d.period==='基期' && d.region===r);
  const c = data.filter(d => d.period==='本期' && d.region===r);
  const bNet = b.reduce((s,d)=>s+d.net_sales_cents,0);
  const cNet = c.reduce((s,d)=>s+d.net_sales_cents,0);
  const bCon = b.reduce((s,d)=>s+d.contribution_cents,0);
  const cCon = c.reduce((s,d)=>s+d.contribution_cents,0);
  return {
    region: r,
    净销售变化率: ((cNet-bNet)/bNet*100).toFixed(1)+'%',
    投放变化率: ((cCon-bCon)/bCon*100).toFixed(1)+'%',
    本期ROI: (cNet/cCon).toFixed(2)
  };
});
result = byRegion;

// 深入分析：本期投放下降最多的渠道和品类交叉情况
// 重点关注"直接访问"和"自然搜索"这两个下降最大的渠道，看看它们关联的品类
const details = data.filter(d => d.period === '本期' && (d.channel === '直接访问' || d.channel === '自然搜索'))
  .map(d => {
    const base = data.find(b => b.period==='基期' && b.channel===d.channel && d.category===b.category && d.region===b.region);
    return {
      channel: d.channel,
      category: d.category,
      region: d.region,
      本期净销售: d.net_sales_cents,
      基期净销售: base ? base.net_sales_cents : 0,
      变化率: base ? ((d.net_sales_cents - base.net_sales_cents)/base.net_sales_cents*100).toFixed(1)+'%' : 'N/A'
    };
  });

// 汇总: 直接访问和自然搜索按品类
const summary = {};
data.filter(d => d.period === '本期' && (d.channel === '直接访问' || d.channel === '自然搜索'))
  .forEach(d => {
    const key = d.channel + '|' + d.category;
    if(!summary[key]) summary[key] = {channel:d.channel, category:d.category, 本期净销售:0, 基期净销售:0};
    summary[key].本期净销售 += d.net_sales_cents;
    const base = data.find(b => b.period==='基期' && b.channel===d.channel && b.category===d.category && b.region===d.region);
    if(base) summary[key].基期净销售 += base.net_sales_cents;
  });

const summaryArr = Object.values(summary).map(s => ({
  ...s,
  变化率: ((s.本期净销售 - s.基期净销售)/s.基期净销售*100).toFixed(1)+'%'
})).sort((a,b) => parseFloat(a.变化率) - parseFloat(b.变化率));

result = summaryArr;

// 最后看看社交拓新这个新渠道的详细情况
const socialNew = data.filter(d => d.period==='本期' && d.channel==='社交拓新');
const byCategorySocial = socialNew.map(d => ({
  category: d.category,
  region: d.region,
  净销售: d.net_sales_cents,
  投放: d.contribution_cents,
  ROI: (d.net_sales_cents / d.contribution_cents).toFixed(2)
}));

// 汇总按品类
const socialByCat = {};
socialNew.forEach(d => {
  if(!socialByCat[d.category]) socialByCat[d.category] = {净销售:0, 投放:0};
  socialByCat[d.category].净销售 += d.net_sales_cents;
  socialByCat[d.category].投放 += d.contribution_cents;
});

result = {
  社交拓新按品类: Object.entries(socialByCat).map(([k,v]) => ({category:k, ...v, ROI: (v.净销售/v.投放).toFixed(2)})),
  社交拓新总体ROI: (socialNew.reduce((s,d)=>s+d.net_sales_cents,0) / socialNew.reduce((s,d)=>s+d.contribution_cents,0)).toFixed(2)
};

// 补充：精选代销的详细拆解，看看是否值得加大投入
const jxBase = data.filter(d => d.period==='基期' && d.category==='精选代销');
const jxCur = data.filter(d => d.period==='本期' && d.category==='精选代销');

const jxByChannel = [...new Set(data.map(d=>d.channel))].map(ch => {
  const b = jxBase.filter(d=>d.channel===ch);
  const c = jxCur.filter(d=>d.channel===ch);
  const bNet = b.reduce((s,d)=>s+d.net_sales_cents,0);
  const cNet = c.reduce((s,d)=>s+d.net_sales_cents,0);
  const bCon = b.reduce((s,d)=>s+d.contribution_cents,0);
  const cCon = c.reduce((s,d)=>s+d.contribution_cents,0);
  if(bNet === 0 && cNet === 0) return null;
  return {
    channel: ch,
    基期净销售: bNet,
    本期净销售: cNet,
    净销售变化: ((cNet-bNet)/Math.max(bNet,1)*100).toFixed(1)+'%',
    基期投放: bCon,
    本期投放: cCon,
    本期ROI: cCon>0 ? (cNet/cCon).toFixed(2) : 'N/A',
    基期ROI: bCon>0 ? (bNet/bCon).toFixed(2) : 'N/A'
  };
}).filter(Boolean);

result = jxByChannel;

