const basePeriod = stat.filter(data, d => d.period === '基期');
const currentPeriod = stat.filter(data, d => d.period === '本期');

const baseNetSales = stat.sum(basePeriod, 'net_sales_cents') / 100;
const currentNetSales = stat.sum(currentPeriod, 'net_sales_cents') / 100;

const baseContribution = stat.sum(basePeriod, 'contribution_cents') / 100;
const currentContribution = stat.sum(currentPeriod, 'contribution_cents') / 100;

const result = [
  {
    period: '基期',
    metric: 'net_sales',
    value_yuan: baseNetSales,
    change_yuan: null,
    change_rate: null
  },
  {
    period: '本期',
    metric: 'net_sales',
    value_yuan: currentNetSales,
    change_yuan: currentNetSales - baseNetSales,
    change_rate: baseNetSales !== 0 ? (currentNetSales - baseNetSales) / baseNetSales : null
  },
  {
    period: '基期',
    metric: 'contribution',
    value_yuan: baseContribution,
    change_yuan: null,
    change_rate: null
  },
  {
    period: '本期',
    metric: 'contribution',
    value_yuan: currentContribution,
    change_yuan: currentContribution - baseContribution,
    change_rate: baseContribution !== 0 ? (currentContribution - baseContribution) / baseContribution : null
  }
];

